(** The functions, decoded as a module. *)
Definition filesync_module : module := Eval vm_compute in
  code_module filesync_term.

(** The term decodes to the module. *)
Lemma filesync_decodes : decode_module filesync_term = Some filesync_module.
Proof. vm_compute. reflexivity. Qed.

(** The function named n of the module, or an empty one. *)
Definition filesync_fn (n : string) : func :=
  code_function filesync_module n.

(** glibc's `_IO_new_file_sync`. *)
Definition glibc__IO_new_file_sync : func := Eval vm_compute in filesync_fn "_IO_new_file_sync".
